#pragma once
#include "api.hpp"
namespace snuw {
inline std::string captionQuery(const std::string& value){std::string out;const char* digits="0123456789ABCDEF";for(unsigned char c:value){if(isalnum(c)&&c<128||c=='-'||c=='_'||c=='.')out+=char(c);else{out+='%';out+=digits[c>>4];out+=digits[c&15];}}return out;}
inline json captionRequest(const json& cfg,const fs::path& image,bool models,const std::atomic_bool* cancel){
 bool account=str(cfg,"api_key")==accountCredential;auto base=str(cfg,account?"api":"caption_api"),key=account?std::string(accountCredential):str(cfg,"caption_api_key");Url endpoint(base);if(endpoint.path!=L"/"||key.empty()||key.find_first_of("\r\n")!=std::string::npos)throw std::runtime_error("로그인과 서버의 캡션 연결 설정을 확인하세요.");
 NetworkScope scope(cancel,std::chrono::steady_clock::now()+std::chrono::seconds(600));
 std::string path="/v1/models",body;
 if(!models){auto model=str(cfg,"caption_model");if(model.empty()||model=="모델을 조회하세요")throw std::runtime_error("캡션 모델을 먼저 선택하세요.");auto format=str(cfg,"caption_format");if(format!="tags"&&format!="sentence")throw std::runtime_error("캡션 형식 오류");std::error_code ec;auto size=fs::file_size(image,ec);if(ec||!size||size>8*1024*1024)throw std::runtime_error("8MB 이하의 이미지 파일을 선택하세요.");std::ifstream input(image,std::ios::binary);body.resize(8*1024*1024+1);input.read(body.data(),body.size());body.resize(size_t(input.gcount()));if(body.empty()||body.size()>8*1024*1024)throw std::runtime_error("이미지 크기 제한 초과");auto mode=str(cfg,"caption_mode","prompt");if(mode!="prompt"&&mode!="training")throw std::runtime_error("캡션 용도 오류");auto workflow=str(cfg,"workflow_profile");std::string pipeline=workflow.find("FLUX")!=std::string::npos?"flux2_klein":workflow.find("Illustrious")!=std::string::npos?"illustrious":"sdxl";path="/v1/captions?model="+captionQuery(model)+"&format="+format+"&mode="+mode+"&pipeline="+pipeline;}
 if(account)path="/api/caption"+path.substr(3);auto response=request(models?"GET":"POST",joinUrl(base,path),key,body,"application/octet-stream",cancel,512*1024,600000);if(response.code==429)throw std::runtime_error("캡션 API 요청 제한입니다. 잠시 후 다시 시도하세요.");auto result=response.object();if(str(result,"api_version")!="0.3.0")throw std::runtime_error("캡션 API가 구버전입니다. 서버 소스를 업데이트하고 재시작하세요 (필요 버전 0.3.0).");if(!models&&(!result.contains("text")||!result["text"].is_string()||result["text"].get<std::string>().empty()||result["text"].get<std::string>().size()>16000))throw std::runtime_error("올바르지 않은 캡션 응답입니다.");
 if(models){if(!result.contains("models")||!result["models"].is_array()||result["models"].size()>200)throw std::runtime_error("모델 목록 응답 오류");for(auto& row:result["models"]){if(!row.is_object()||!row.contains("name")||!row["name"].is_string()||row["name"].get<std::string>().empty()||row["name"].get<std::string>().size()>200)throw std::runtime_error("모델 이름 응답 오류");}}return result;
}
}
